            "Name": "customer_name",
            "Type": "customer_type",
            "Industry": "industry",
            "Phone": "phone",
            "BillingCity": "billing_city",
            "BillingState": "billing_state",
            "BillingCountry": "billing_country",
            "CreatedDate": "created_date",
            "LastModifiedDate": "last_modified_date",
